sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || isTemplate) {
        return;
    }
    if (!newValue) {
        g_form.clearValue('participant_assignment');
        g_form.clearValue('user');
        return;
    }

    populateFromPlanAssignment();

}

function populateFromPlanAssignment() {

    var planAssignmentId = g_form.getValue('plan_assignment');

    if (!planAssignmentId)
        return;

    var ga = new GlideAjax('IncentNowClientUtils');
    ga.addParam('sysparm_name', 'getPlanAssignmentDetails');
    ga.addParam('sysparm_plan_assignment', planAssignmentId);
    ga.getXMLAnswer(function(answer) {

        if (!answer)
            return;

        var result;

        try {
            result = JSON.parse(answer);
        } catch (e) {
            return;
        }

        if (!result.success)
            return;

        if (result.participant_assignment) {
            g_form.setValue('participant_assignment', result.participant_assignment);
			g_form.setReadOnly(' participant_assignment', true);
        }

        if (result.user) {
            g_form.setValue('user', result.user);
			g_form.setReadOnly('user', true);
        }
    });
}
